window.NEWS_SNAP={"asof": "2026-09-24 07:44", "sources": [{"name": "金十·PLUS实时", "ok": true, "n": 20}, {"name": "先讯·延时", "ok": true, "mode": "delayed", "n": 30}, {"name": "CS财经·实时", "ok": true, "n": 30}, {"name": "东财7x24", "ok": true, "n": 40}, {"name": "新浪7x24", "ok": true, "n": 40}, {"name": "LME锡铜·westmetall", "ok": true, "n": 10}], "jin10": [{"src": "jin10", "time": "2026-09-24 07:38:25", "ts": "2026-09-24 07:38:25", "content": "金十提示：日本股市结束“白银周”连假，今日起恢复交易。因中秋节假期，韩国股市今日起休市两日。", "important": 0, "vip": 0, "tags": [], "id": "20260924073825352800"}, {"src": "jin10", "time": "2026-09-24 07:35:35", "ts": "2026-09-24 07:35:35", "content": "【软银拟发行100亿美元美元债】金十数据9月24日讯，软银集团计划发行总规模100亿美元的美元计价债券。其中，包括10亿美元2030年到期票据，票面利率为8.625%；45亿美元2032年到期债券，票面利率为9.250%；以及45亿美元2034年到期债券，票面利率为9.750%。", "important": 0, "vip": 0, "tags": [], "id": "20260924073535171800"}, {"src": "jin10", "time": "2026-09-24 07:34:56", "ts": "2026-09-24 07:34:56", "content": "【现货价格】金十期货09月24日讯，今日全国内三元生猪价格涨跌情况一览。", "important": 0, "vip": 0, "tags": [], "id": "20260924073456965800"}, {"src": "jin10", "time": "2026-09-24 07:34:37", "ts": "2026-09-24 07:34:37", "content": "【现货价格】金十期货09月24日讯，今日全国外三元生猪价格涨跌情况一览。", "important": 0, "vip": 0, "tags": [], "id": "20260924073437104800"}, {"src": "jin10", "time": "2026-09-24 07:29:50", "ts": "2026-09-24 07:29:50", "content": "软银集团将发行10亿美元的美元计价票据，票面利率为8.625%，到期日为2030年。", "important": 0, "vip": 0, "tags": [], "id": "20260924072950085800"}, {"src": "jin10", "time": "2026-09-24 07:29:45", "ts": "2026-09-24 07:29:45", "content": "【Meta推出无摄像头版智能眼镜，引入Muse助手功能】金十数据9月24日讯，Meta Platforms(META.O)正在扩展其智能眼镜产品线，推出无摄像头版本，并将Muse助手功能引入旗下智能眼镜产品。在周三举行的Connect年度大会上，该公司发布了首款不搭载摄像头的Ray-Ban Meta Audio智能眼镜。同时，Meta还推出了第三代搭载摄像头的Ray-Ban Meta眼镜，以及新款价格更低的Meta品牌智能眼镜。这款主打音频功能的眼镜，为Meta重新探索这一曾因隐私问题引发争议的产品类别提供了机会。Meta无摄像头眼镜起售价为349美元，计划于10月3日开始发货。第三代机型还配备了一个新的“操作按钮”，用户可以对其进行自定义设置，用于执行特定任务，例如启动Muse语音助手。", "important": 0, "vip": 0, "tags": [], "id": "20260924072945767800"}, {"src": "jin10", "time": "2026-09-24 07:25:47", "ts": "2026-09-24 07:25:47", "content": "委内瑞拉临时总统罗德里格斯：委内瑞拉已开始民主进程；呼吁进行政治对话以实现自由与和解。", "important": 0, "vip": 0, "tags": [], "id": "20260924072547142800"}, {"src": "jin10", "time": "2026-09-24 07:20:51", "ts": "2026-09-24 07:20:51", "content": "委内瑞拉临时总统罗德里格斯：渴望与美国及其邻国建立关系。", "important": 0, "vip": 0, "tags": [], "id": "20260924072051107800"}, {"src": "jin10", "time": "2026-09-24 07:20:45", "ts": "2026-09-24 07:20:45", "content": "委内瑞拉临时总统罗德里格斯：感谢美国总统特朗普恢复外交关系。", "important": 0, "vip": 0, "tags": [], "id": "20260924072045778800"}, {"src": "jin10", "time": "2026-09-24 07:19:43", "ts": "2026-09-24 07:19:43", "content": "Meta Platforms(META.O)：将把Muse整合至公司所有的智能眼镜产品中。", "important": 0, "vip": 0, "tags": [], "id": "20260924071943722800"}, {"src": "jin10", "time": "2026-09-24 07:18:54", "ts": "2026-09-24 07:18:54", "content": "委内瑞拉临时总统罗德里格斯：我敦促圭亚那重返谈判桌。", "important": 0, "vip": 0, "tags": [], "id": "20260924071854413800"}, {"src": "jin10", "time": "2026-09-24 07:18:47", "ts": "2026-09-24 07:18:47", "content": "委内瑞拉临时总统罗德里格斯：近期与美国达成的能源交易将有助于全球能源平衡。", "important": 0, "vip": 0, "tags": [], "id": "20260924071847106800"}, {"src": "jin10", "time": "2026-09-24 07:18:27", "ts": "2026-09-24 07:18:27", "content": "【金十数据整理：每日科技要闻速递（9月24日）】人工智能：1. 千问发布Qwen-Audio-3.1，下调Qwen-Audio全线语音模型价格。2. 英伟达支持的Firmus公司寻求100亿美元融资，用于开发人工智能芯片。3. Meta将推出无摄像头智能眼镜，应对AI隐私担忧。4. SpaceX AI智能体GrokBot上线首月，周用户数突破40万。5. 澳总理：OpenAI智能体入侵澳政府网站，且过晚通报。6. Anthropic首席执行官：由于安全的缘故，公司将放慢AI的研发进度。7. 阿里千问发布Qwen-Audio-3.1系列语音大模型，并下调全线产品价格。其他：1. 我国将适度超前、系统推进新一代通信网建设。2. 我国成功发射卫星互联网低轨26组卫星。3. 小马智行2026上半年归母净亏损1.1亿美元，同比亏损扩大14.74%。4. 报道：台积电晶圆代工价格确定再涨，涨幅约3%至6%。", "important": 0, "vip": 0, "tags": [], "id": "20260924071827221800"}, {"src": "jin10", "time": "2026-09-24 07:16:00", "ts": "2026-09-24 07:16:00", "content": "孟加拉国航空公司向波音(BA.N)订购11架787梦想飞机和737 MAX飞机。", "important": 0, "vip": 0, "tags": [], "id": "20260924071600632800"}, {"src": "jin10", "time": "2026-09-24 07:14:25", "ts": "2026-09-24 07:14:25", "content": "Meta Platforms(META.O)高管：公司正在为Muse增加计算机操作功能。", "important": 0, "vip": 0, "tags": [], "id": "20260924071425103800"}, {"src": "jin10", "time": "2026-09-24 07:08:25", "ts": "2026-09-24 07:08:25", "content": "欧洲理事会主席科斯塔：我呼吁结束伊朗对邻国的攻击，并全面恢复霍尔木兹海峡的航行自由。", "important": 0, "vip": 0, "tags": [], "id": "20260924070825738800"}, {"src": "jin10", "time": "2026-09-24 07:08:22", "ts": "2026-09-24 07:08:22", "content": "欧洲理事会主席科斯塔：与伊朗总统进行了通话，敦促伊朗恢复与国际原子能机构的合作。", "important": 0, "vip": 0, "tags": [], "id": "20260924070822159800"}, {"src": "jin10", "time": "2026-09-24 07:03:31", "ts": "2026-09-24 07:03:31", "content": "美债收益率全线上涨，5年期美债收益率2007年以来首次升破5%；白宫否认柴油出口禁令相关报道；台积电晶圆代工价格确定再涨……昨日今晨，全球都发生了哪些大事？", "important": 1, "vip": 0, "tags": [], "id": "20260924070331106800"}, {"src": "jin10", "time": "2026-09-24 07:02:29", "ts": "2026-09-24 07:02:29", "content": "全球最大白银ETF--iShares Silver Trust持仓较上日减少25.28吨，当前持仓量为15350.6吨。欢迎点击查看数据中心...", "important": 1, "vip": 0, "tags": [], "id": "20260924070229610800"}, {"src": "jin10", "time": "2026-09-24 06:54:58", "ts": "2026-09-24 06:54:58", "content": "美国财长贝森特表示，（霍尔木兹海峡的）部分油轮可能会遭到袭击，但很多油轮仍会继续航行。伊朗方面可能会派出3架、4架、5架甚至6架无人机追击，但强大的美国海军正在进行拦截。目前，我们每天仍有1000万至1500万桶、有时甚至1700万桶石油运出。作为对比，在冲突开始前，这一数字为2000万桶左右。此外，可能还有约300万桶石油通过其他替代渠道出口。谈及伊朗局势，贝森特称大致有三种可能的结果：1. 伊朗政权内部互相攻击；2. 伊朗政权被推翻，以及3. 伊朗达成并遵守协议。贝森特表示，“这次如果达成协议，我保证他们会信守承诺！”", "important": 0, "vip": 0, "tags": [], "id": "20260924065458551800"}], "ah": [{"src": "ah", "time": "09-23 07:41", "ts": "2026-09-23 07:41", "content": "微软将随着推出AI“超级应用”而增加Copilot折扣 - The Information", "logic": "微软通过降低AI助手Copilot的门槛来推广其全新的AI超级应用生态，旨在扩大AI应用的市场占有率并增强用户粘性。这利好软件服务及AI应用板块，但也需警惕折扣策略对短期利润率可能带来的压力。", "sentiment": "利多", "level": "S", "source": "VIP终端", "importance": 100}, {"src": "ah", "time": "09-23 07:39", "ts": "2026-09-23 07:39", "content": "英国首相安迪·伯纳姆称他在与总统唐纳德·特朗普的会谈中重申了英国对福克兰群岛的立场，表示英国将‘坚定立场’并捍卫岛民的自决权以及作为英国人的权利。福克兰群岛是包括乌克兰和贸易在内的多个议题之一，随着英国与阿根廷的主权争端在进一步英美会谈前仍是一个敏感问题。", "logic": "英国重申对福克兰群岛的主权立场，可能增强相关地区投资者信心，但可能引发与阿根廷的紧张关系，影响英美关系及区域政治风险。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:38", "ts": "2026-09-23 07:38", "content": "美国特使史蒂夫·惠特科夫：我们通过中间人与伊朗代表团在纽约进行了长时间的会谈\n#الشرق_عاجل 美国特使史蒂夫·惠特科夫：我们通过中间人与伊朗代表团在纽约进行了长时间的会谈 - 东方紧急 ASHARQ 突发", "logic": "该快讯可能改变相关资产的短线定价和波动率，方向取决于现有市场预期；需结合后续细节确认影响。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:36", "ts": "2026-09-23 07:36", "content": "SB能源计划在SEC审查完成后开始IPO营销", "logic": "海外能源公司IPO动作利好国内新能源产业链", "sentiment": "利多", "level": "B", "source": "Bloomberg", "importance": 68}, {"src": "ah", "time": "09-23 07:36", "ts": "2026-09-23 07:36", "content": "如果你15年前投资了Casella Waste Systems股票，今天你将拥有这么多", "logic": "美股环保股表现良好映射A股环保板块", "sentiment": "利多", "level": "B", "source": "Benzinga", "importance": 59}, {"src": "ah", "time": "09-23 07:36", "ts": "2026-09-23 07:36", "content": "美国特使维特科夫表示，他通过调解人与伊朗代表团进行了长时间会谈，调解人将继续他们的工作，并补充说他希望这些会谈能取得建设性和有前景的结果", "logic": "美伊会谈进展被报道 -&gt; 市场预期可能缓解地缘政治风险 -&gt; 与中东相关的能源和军事板块 -&gt; 会谈结果不确定导致风险持续存在", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:36", "ts": "2026-09-23 07:36", "content": "$1,000 在每一次主要的“比特币已死”言论中投资，将价值：2011年，《福布斯》：4,922,700美元；2014年，沃伦·巴菲特：127,400美元；2017年，杰米·戴蒙：20,700美元；2018年，沃伦·巴菲特：8,800美元；2019年，唐纳德·特朗普：7,300美元；2022年，欧洲央行：5,000美元；2023年，查理·芒格：3,550美元；2024年，欧洲央行：1,700美元", "logic": "事件为比特币相关预言的回测结果。市场预期可能因历史数据而波动，但不同资产类别受影响程度不一。主要影响加密货币板块，风险点在于市场情绪与实际表现的偏离。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:30", "ts": "2026-09-23 07:30", "content": "伊朗还呼吁结束所有“抵抗”前线的战争，同时通过霍尔木兹海峡的航运仍严重受阻，周一仅有两艘商品货轮通过，而冲突前的平均每天约有125艘大型商业船只通过。", "logic": "事件：伊朗呼吁结束战争，但霍尔木兹海峡航运受阻。市场预期：地缘政治风险上升，能源供应担忧加剧。相关板块：能源、航运、避险资产。风险点：全球供应链中断和油价波动。", "sentiment": "利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:30", "ts": "2026-09-23 07:30", "content": "伊朗国家媒体称外交部长阿巴斯·阿拉格奇在联合国大会期间与美国特使史蒂夫·维特科夫会面，德黑兰表示会谈集中在其重新开放霍尔木兹海峡的条件上，包括解除美国海军封锁和解冻伊朗被冻结资产。", "logic": "伊朗与美国官员会面 -&gt; 可能缓解地区紧张局势 -&gt; 海运相关板块或受益 -&gt; 需关注后续谈判进展及地缘政治风险", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:24", "ts": "2026-09-23 07:24", "content": "特朗普批评英国与毛里求斯的查戈斯群岛交易为“糟糕的交易”，涉及战略军事领土，同时伯纳姆承诺对沙特阿拉伯在胡塞武装袭击中的支持有限，呼吁美国为乌克兰提供更多防空支持，并推动全球人工智能原则", "logic": "美国政治人物言论引发地缘政治不确定性，可能影响国际关系及军事合作，对相关国家的外交政策和安全板块产生影响，需关注后续政策变化及市场反应。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:24", "ts": "2026-09-23 07:24", "content": "特朗普在与英国首相安迪·伯纳姆的首次联合国会议后称赞他为“天生的商人”，同时表示领导人就贸易、中东、乌克兰和人工智能进行了广泛讨论。", "logic": "特朗普对英国首相的正面评价可能提升市场对其外交政策的信心，但具体影响需看后续政策走向。相关板块包括国际关系及科技领域。风险点在于地缘政治紧张局势可能持续。", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:20", "ts": "2026-09-23 07:20", "content": "伊朗外长阿拉格奇在联合国大会期间与伊拉克同僚会面 - TASNIM", "logic": "伊朗与伊拉克官员会面 -&gt; 可能影响地区政治关系 -&gt; 中东地缘政治板块 -&gt; 未提及具体经济影响", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:19", "ts": "2026-09-23 07:19", "content": "智库称应削减英国国家养老金改革", "logic": "养老金改革影响保险业盈利预期", "sentiment": "利空", "level": "B", "source": "Bloomberg", "importance": 60}, {"src": "ah", "time": "09-23 07:19", "ts": "2026-09-23 07:19", "content": "澳航看涨澳大利亚夏季旅游预订，尽管成本激增", "logic": "旅游需求增加利好相关行业", "sentiment": "利多", "level": "B", "source": "Bloomberg", "importance": 60}, {"src": "ah", "time": "09-23 07:16", "ts": "2026-09-23 07:16", "content": "特朗普签署与丹麦和格陵兰的三方安全协议，扩大美国在北极岛屿的军事存在，包括在纳尔萨鲁阿克和梅斯特斯维格新增两个基地，同时格陵兰仍处于丹麦主权之下。该协议扩大了皮图夫克太空基地，使格陵兰成为黄金穹顶防御系统的一部分，赋予美国在安全和敏感投资方面更大的作用，并要求未来独立的格陵兰必须留在北约内。", "logic": "美国扩大在北极地区的军事部署，可能提升地缘政治紧张局势，对国防板块有利，但可能引发地区冲突风险，影响全球能源和贸易路线安全。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:13", "ts": "2026-09-23 07:13", "content": "以色列常驻联合国大使丹尼·丹农称，关于伊朗，'我们知道伊朗领导人藏在哪里'和'他们正在做什么'，并补充说'如果他们攻击以色列，我们只需要几天时间就能找到他们'", "logic": "以色列官员公开威胁伊朗，可能引发地区紧张局势升级，市场预期中东冲突风险上升，相关板块如能源、避险资产可能受到影响，但具体影响方向取决于事件发展。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:13", "ts": "2026-09-23 07:13", "content": "以色列常驻联合国大使丹尼·丹农表示：‘如果有人应该被逮捕，那么市长马姆达尼应因他的行为被逮捕’。", "logic": "事件是外交官员对某市长的批评，可能引发地区紧张局势升级，影响国际关系及地缘政治风险，相关板块包括国际关系敏感地区股票及避险资产。", "sentiment": "利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:12", "ts": "2026-09-23 07:12", "content": "泽连斯基警告俄罗斯正在准备对乌克兰的“大规模攻击”，援引情报报告", "logic": "事件：泽连斯基警告俄罗斯将发动大规模攻击。市场预期/传导链：引发地缘政治风险担忧。相关板块：避险资产、能源、军工。风险点：冲突升级可能影响全球市场情绪和大宗商品价格。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:12", "ts": "2026-09-23 07:12", "content": "美国国务卿鲁比奥称‘对俄罗斯来说这场战争很糟糕’，并称‘他们在战争中并不顺利’，认为‘停止战争完全合情合理’，但补充称‘在外交政策和此类问题上，有时合情合理的做法未必会发生’", "logic": "事件为美国国务卿批评俄罗斯在战争中的表现，市场预期可能加剧地缘政治风险，相关板块包括能源、军工及避险资产，风险点在于冲突升级或制裁进一步收紧。", "sentiment": "利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:12", "ts": "2026-09-23 07:12", "content": "美国国务卿马可·鲁比奥表示'我要明确：美国从不针对平民。永远不'，并称在战争中'一些平民会遭殃'，但美国不会针对他们，并称针对平民的国家是伊朗。", "logic": "事件 -&gt; 市场预期/传导链 -&gt; 相关板块 -&gt; 风险点：美国官员重申不针对平民，可能影响国际关系和地缘政治风险，对能源和军工板块有潜在影响。", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:11", "ts": "2026-09-23 07:11", "content": "美国国务卿马可·鲁比奥对伊朗表示：伊朗针对本国人民的行动引发了对美国、以色列及地区邻国威胁的担忧", "logic": "事件：美国官员批评伊朗行为。市场预期/传导链：可能引发地缘政治紧张。相关板块：中东地区股票、能源板块。风险点：地区冲突升级影响全球市场。", "sentiment": "利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:11", "ts": "2026-09-23 07:11", "content": "美国国务卿马可·鲁比奥：伊朗拥有核武器可能威胁关闭霍尔木兹海峡并阻止其他人介入", "logic": "事件：伊朗可能获得核武器。市场预期/传导链：地缘政治风险上升。相关板块：能源、军工、避险资产。风险点：中东局势紧张可能导致油价波动和市场避险情绪升温。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:10", "ts": "2026-09-23 07:10", "content": "美国国务卿马可·鲁比奥关于格陵兰岛的声明：协议适用于格陵兰岛是否独立；称其地位将由格陵兰人决定", "logic": "事件为美国国务卿对格陵兰岛地位的表态，市场预期可能涉及地缘政治风险，相关板块可能包括矿业和能源，风险点在于未来政策变化带来的不确定性。", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:10", "ts": "2026-09-23 07:10", "content": "美国国务卿马可·鲁比奥：格陵兰对美国国家安全至关重要；称美国不能冒险让中国或俄罗斯在该地建立基地", "logic": "美国强调格陵兰战略重要性，可能引发地缘政治紧张，影响全球安全预期。相关板块包括国防、军工、地缘政治敏感地区资源。风险点在于地缘冲突升级及国际关系波动。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:09", "ts": "2026-09-23 07:09", "content": "澳大利亚9月标普全球服务业PMI初值录得51.4，低于8月的53.2", "logic": "服务业PMI增速放缓反映澳洲经济扩张动能减弱，可能对澳元及大宗商品需求产生压制，进而影响相关资源类板块。需关注后续通胀数据对澳洲央行政策的影响。", "sentiment": "利空", "level": "S", "source": "VIP终端", "importance": 100}, {"src": "ah", "time": "09-23 07:08", "ts": "2026-09-23 07:08", "content": "巴格达和马斯喀特机场暂停伊朗航班；阿塞拜疆也暂停飞往伊朗的航班 —— FARS", "logic": "航班暂停事件 -&gt; 航空运输及旅游相关市场预期变化 -&gt; 航空、旅游板块 -&gt; 地缘政治风险加剧", "sentiment": "利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:08", "ts": "2026-09-23 07:08", "content": "加拿大央行行长卡尼：美国与中国有更深层次的合作，加拿大与中国合作较少；认为有扩大向美国出口钾肥的潜力，并支持人工智能监管", "logic": "事件为加拿大央行行长言论，提及美中合作较加中更深入，可能影响加中贸易关系；市场预期可能关注加拿大对华政策变化及钾肥出口前景；相关板块包括农业、矿业及国际关系；风险点在于地缘政治对贸易的影响。", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:05", "ts": "2026-09-23 07:05", "content": "美国API汽油库存下降216万桶，馏分油库存下降216.4万桶，两者均逆转此前增长，并表明精炼产品库存更加紧张。", "logic": "库存下降表明供应紧张，可能推高油价，对能源板块有利；但若需求疲软则可能利空。相关板块包括原油、能源股。风险点在于供需变化及经济数据影响。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:05", "ts": "2026-09-23 07:05", "content": "美国API原油库存增加178.6万桶，逆转此前710万桶的增幅，但超过预期的50万桶降幅，同时库欣库存增加208.2万桶", "logic": "原油库存增加表明供应压力上升，可能对油价形成利空；但库存增幅低于预期，可能对油价形成利多。市场预期可能分化，影响能源板块及大宗商品相关资产。", "sentiment": "利多/利空", "level": "S", "source": "先讯终端", "importance": 100}, {"src": "ah", "time": "09-23 07:05", "ts": "2026-09-23 07:05", "content": "FORTRESS：截至2026年8月31日，该基金的组合在92家公司和21个行业中具有20亿美元的公允价值，而它在9月出售了2580万美元的I类普通股。", "logic": "基金组合公允价值高显示资产质量良好，但出售股票可能引发市场对资金流动的担忧。影响板块可能包括基金相关股票及金融板块。风险点在于资金流出可能对股价造成压力。", "sentiment": "中性", "level": "S", "source": "先讯终端", "importance": 100}], "cs": [{"src": "cs", "time": "2026-09-24 07:39:18", "ts": "2026-09-24 07:39:18", "content": "【也门胡塞武装：近期逾400艘商船通过曼德海峡】也门胡塞武装9月23日称，尽管连接红海与亚丁湾的重要水道曼德海峡附近战事持续，近期仍有超过400艘商船通过这一战略水道。据胡塞武装控制的马西拉电视台援引该组织声明报道，9月11日至21日，共有408艘商船通过曼德海峡，其中196艘向北驶往红海，212艘向南驶往亚丁湾。报道说，通过曼德海峡的商船包括集装箱船，“除沙特船只外，国际航运仍在正常、安全进行”。报道还说，这一数字高于9月1日至10日期间记录的393艘商船。这其中，199艘船向北航行，194艘向南航行。", "tags": ["环球市场情报"], "id": 256758}, {"src": "cs", "time": "2026-09-24 07:37:12", "ts": "2026-09-24 07:37:12", "content": "【Meta推出无摄像头版智能眼镜 引入Muse助手功能】Meta Platforms正在扩展其智能眼镜产品线，推出无摄像头版本，并将Muse助手功能引入旗下智能眼镜产品。在周三举行的Connect年度大会上，该公司发布了首款不搭载摄像头的Ray-Ban Meta Audio智能眼镜。同时，Meta还推出了第三代搭载摄像头的Ray-Ban Meta眼镜，以及新款价格更低的Meta品牌智能眼镜。这款主打音频功能的眼镜，为Meta重新探索这一曾因隐私问题引发争议的产品类别提供了机会。Meta无摄像头眼镜起售价为349美元，计划于10月3日开始发货第三代机型还配备了一个新的“操作按钮”，用户可以对其进行自定义设置，用于执行特定任务，例如启动Muse语音助手。", "tags": ["摄像头", "环球市场情报"], "id": 256757}, {"src": "cs", "time": "2026-09-24 07:32:51", "ts": "2026-09-24 07:32:51", "content": "【A股限售股解禁一览：9.26亿元市值限售股今日解禁】Wind数据显示，周四（9月24日），共有10家公司限售股解禁，合计解禁量为4829.53万股，按最新收盘价计算，合计解禁市值为9.26亿元。从解禁量来看，振华重工、陕鼓动力、杰华特解禁量居前，解禁股数分别为2269.01万股、1477.99万股、454.68万股。从解禁市值来看，杰华特、陕鼓动力、振华重工解禁市值居前，解禁市值分别为5.42亿元、1.32亿元、9234.88万元。从解禁股数占总股本比例来看，力王股份、杰华特、派诺科技解禁比例居前，解禁比例分别为2.41%、1.0%、0.93%。", "tags": ["限售股解禁"], "id": 256756}, {"src": "cs", "time": "2026-09-24 07:17:45", "ts": "2026-09-24 07:17:45", "content": "Meta首席执行官扎克伯格表示，公司预计将通过从每笔交易中收取少量手续费来从Muse获得收益。", "tags": ["环球市场情报"], "id": 256755}, {"src": "cs", "time": "2026-09-24 07:15:21", "ts": "2026-09-24 07:15:21", "content": "Meta Platforms高管称，公司正在为Muse增加计算机操作功能。", "tags": ["环球市场情报"], "id": 256754}, {"src": "cs", "time": "2026-09-24 07:05:03", "ts": "2026-09-24 07:05:03", "content": "软银将发行约111亿美元的优先票据，到期日为2030年至2034年。", "tags": ["环球市场情报"], "id": 256752}, {"src": "cs", "time": "2026-09-24 07:02:14", "ts": "2026-09-24 07:02:14", "content": "【科学家直接捕捉到系外行星射电信号】宇宙深处，一束微弱无线电波穿过约64光年时空。美国哈佛—史密森天体物理中心的科学家利用位于南非的MeerKAT射电望远镜，观测了β Pictoris行星系统，捕捉到来自其巨行星β Pictoris b的射电信号。这可能是人类首次明确探测到来自系外行星的射电信号，有助于检验行星内部理论模型。 （科技日报）", "tags": ["环球市场情报"], "id": 256751}, {"src": "cs", "time": "2026-09-24 06:56:59", "ts": "2026-09-24 06:56:59", "content": "【量子模拟器再现高能物理“弦断裂”过程】美国杜克大学研究团队利用13个囚禁离子组成的量子模拟器，再现了高能物理中的“弦断裂”过程，观测到与粒子-反粒子形成有关的动力学。这是量子物理领域的一项重要进展，也为理解弦断裂动力学开辟了新途径。相关研究23日发表于《自然·物理学》杂志。", "tags": ["环球市场情报"], "id": 256750}, {"src": "cs", "time": "2026-09-24 06:55:32", "ts": "2026-09-24 06:55:32", "content": "澳大利亚三年期国债收益率涨14个基点，创2011年以来新高。", "tags": ["环球市场情报"], "id": 256749}, {"src": "cs", "time": "2026-09-24 06:34:32", "ts": "2026-09-24 06:34:32", "content": "【规模情结驱动降费潮 理财行业亟须跳出价格战】近日，理财公司降费潮再次来袭，部分理财产品固定管理费率已逼近0。在固收类产品收益率下行、产品同质化严重的背景下，“卷费率”成为理财公司“以价换量”、争夺存量资金的重要手段。记者注意到，由于渠道端拥有强势话语权，理财行业降费多从固定管理费“开刀”，对销售服务费甚少触及。管理费是理财公司营业收入的重要来源。持续的价格战容易让行业陷入内卷，对行业的长期能力建设和商业可持续造成不利影响。 （中证报）", "tags": ["银行理财"], "id": 256748}, {"src": "cs", "time": "2026-09-24 06:28:54", "ts": "2026-09-24 06:28:54", "content": "【AI算力与新硬件布局落地 消费电子业绩持续兑现】从多家A股消费电子公司半年度业绩说明会释放的信息来看，行业正逐步摆脱手机、PC等传统业务依赖，加速向AI算力、机器人、AI眼镜等赛道布局。算力赛道上，多家公司借技术攻坚、扩产及并购，加码算力整机、液冷散热等核心环节，多款产品预计下半年批量生产。此外，依托精密制造的优势，不少公司加码布局折叠屏材料、AI可穿戴等新业务，多线培育增长新动能。 （上证报）", "tags": ["人工智能", "机器人", "算力", "智能手机前沿观察", "消费电子", "AI眼镜"], "id": 256747}, {"src": "cs", "time": "2026-09-24 06:27:15", "ts": "2026-09-24 06:27:15", "content": "【PCB涨价向下游传导顺畅 更多行业应用开始起量】A股PCB（印制电路板）概念股9月23日强势领涨，中一科技、集泰股份、澳弘电子、江南新材、依顿电子等多只个股涨停。消息面上，江西省宏瑞兴科技股份有限公司、松下、南亚塑胶等公司近期再度上调覆铜板（CCL）等产品价格。记者调研产业链获悉，当前PCB产业出现显著变化：一方面，比上游涨价更为值得关注的是，PCB板厂迎来盈利修复窗口；另一方面，产业成长驱动力也在悄然蓄势，除了AI算力动能持续强劲，机器人、光模块等新成长动能已初现端倪，整个产业进入“强者恒强”的发展格局。 （上证报）", "tags": ["TMT行业观察", "人工智能", "机器人", "算力", "有色·铜", "PCB", "光模块"], "id": 256746}, {"src": "cs", "time": "2026-09-24 06:25:10", "ts": "2026-09-24 06:25:10", "content": "【公募秋季策略会密集召开 积极看多权益资产】金秋布局正当时，公募基金开启“秋播”窗口。近期，华宝基金、建信基金、汇丰晋信基金、富国基金等多家基金公司举行秋季投资策略会，研判后市投资机遇。综合来看，机构普遍看好权益资产配置价值，认为有较多投资机会可以把握。从投资方向看，AI依然是重要的投资主线。 （上证报）", "tags": ["人工智能", "公募基金动态"], "id": 256745}, {"src": "cs", "time": "2026-09-24 06:23:40", "ts": "2026-09-24 06:23:40", "content": "【加仓意愿再度集聚 股票私募仓位两周连涨】近日，私募基金加仓态势明显。私募排排网数据显示，截至9月18日，股票私募仓位指数（有业绩记录的主观多头股票策略私募产品平均仓位水平）连续两周上涨。从结构来看，截至9月18日，仓位超过八成的私募占比高达67%以上。在业内人士看来，经过前段时间的估值消化，市场结构性行情大概率将转向盈利兑现方向，投资机会或进一步扩散。 （上证报）", "tags": ["证券私募动态"], "id": 256744}, {"src": "cs", "time": "2026-09-24 06:22:22", "ts": "2026-09-24 06:22:22", "content": "【9月银行理财规模延续高增态势】继8月银行理财规模高增后，记者从业内获取的最新数据显示，9月以来这一态势仍在延续。从增量结构看，含权类产品是本轮理财规模增长的重要增量来源。不过，规模持续攀高，并未为理财公司带来明显的赚钱效应。业内人士对记者表示，规模增长要想真正转化为盈利增长，还有待机构提升投研、产品和风险管理能力。 （上证报）", "tags": ["银行业动态", "银行理财"], "id": 256743}, {"src": "cs", "time": "2026-09-24 06:15:39", "ts": "2026-09-24 06:15:39", "content": "【习近平主席抵达华盛顿 特朗普总统机场迎接】当地时间9月23日下午，国家主席习近平乘专机抵达华盛顿，应美国总统特朗普邀请，对美国进行国事访问。习近平和夫人彭丽媛抵达华盛顿安德鲁斯空军基地时，特朗普和夫人梅拉尼娅热情迎接。 （新华社）", "tags": [], "id": 256742}, {"src": "cs", "time": "2026-09-24 06:15:16", "ts": "2026-09-24 06:15:16", "content": "【周四你需要知道的隔夜全球要闻：美联储10月加息预期增强，欧美股市全线下跌，联合国安理会召开人工智能相关会议，台积电将上调晶圆代工价格3%至6%】\n1、美国PMI数据公布后，市场预计美联储在10月会议上至少加息25个基点的概率升至约75%，数据公布前约为53%。\n2、联合国安理会召开人工智能相关会议，奥尔特曼等多位知名企业家发表AI有关言论。\n3、供应链人士透露，台积电已确定自2027年1月起，按照不同制程调整Wafer Out价格，涨幅约3%-6%。\n4、美联储理事巴尔表示，通胀并未明确地以及时的方式向2%目标靠拢。\n5、美国财政部将于周四回购至多60亿美元的长期债券。\n6、据报道，美国监管机构计划加快新型电子烟产品的审批流程。\n7、伊朗最高国家安全委员会秘书穆赫辛·雷扎伊表示，只要伊朗的条件未得到满足，霍尔木兹海峡就不会重新开放，也不会进行任何谈判。\n8、伊朗总统佩泽希齐扬表示，伊朗需要的是核能，而非核武器。\n9、伊朗外交部发言人称，伊朗在向美国进行的两个小时进程中阐明了恢复外交的条件。\n10、以色列议会批准追加近150亿新谢克尔国防预算。\n11、印度政府下调棕榈油和大豆油、葵花油的进口关税。\n12、美股三大指数集体收跌，纳指跌1.13%，标普500指数跌0.75%，道指跌0.68%。欧洲主要股指收盘集体下跌，德国DAX30指数跌0.59%。\n13、COMEX黄金期货跌1.23%，报4322.7美元/盎司；COMEX白银期货跌2.4%，报64.93美元/盎司。\n14、国际原油期货结算价收涨。WTI原油期货11月合约涨1.81%，布伦特原油期货11月合约涨3.86%。\n15、微软计划到2030年在中东地区投资4亿美元用于海底和陆地连接。\n16、美国总统特朗普儿子Trump JR.旗下1789 Capital洽谈融资30亿美元。\n17、谷歌推出Gemini 3.8 Flash TTS音频模型。\n18、高通公司表示将收购机器人软件公司Picknik。\n19、Anthropic成立生命科学研究实验室。\n20、派拉蒙据称考虑引入马斯克及其他富豪人士进行投资。\n21、嘉能可与美国进出口银行合作建立战略矿产储备基金，美国进出口银行承诺提供5亿美元资金。\n22、Myseum AI将申请对纳斯达克上市普通股进行代币化。", "tags": ["提醒电报"], "id": 256741}, {"src": "cs", "time": "2026-09-24 06:03:31", "ts": "2026-09-24 06:03:31", "content": "【美联储10月加息的概率抬升至69.7%】据CME“美联储观察”：美联储10月会议维持利率在3.75%-4.00%不变的概率为30.3%，加息25个基点的概率为69.7%。美联储到12月维持利率在3.75%-4.00%不变的概率为6.5%，累计加息25个基点的概率为38.7%，累计加息50个基点的概率为54.8%。", "tags": ["环球市场情报"], "id": 256740}, {"src": "cs", "time": "2026-09-24 06:00:13", "ts": "2026-09-24 06:00:13", "content": "【周四（9月24日）重点关注财经事件和经济数据】\n①待定 国内成品油开启新一轮调价窗口；\n②09:30 澳大利亚8月季调后失业率；\n③15:30 瑞士央行公布利率决议；\n④16:00 德国9月IFO商业景气指数；\n⑤16:10 美联储威廉姆斯参加谈话；\n⑥18:00 英国9月CBI零售销售差值；\n⑦20:00 美联储巴尔金参加谈话；\n⑧20:30 美国至9月19日当周初请失业金人数、美国第二季度经常帐，加拿大7月零售销售月率； \n⑨20:50 美联储哈马克发表讲话； \n⑩22:00 美国8月新屋销售总数年化； \n⑪22:10 美联储保尔森发表讲话； \n⑫22:30 美国至9月18日当周EIA天然气库存。", "tags": ["提醒电报"], "id": 256739}, {"src": "cs", "time": "2026-09-24 05:58:36", "ts": "2026-09-24 05:58:36", "content": "据巴基斯坦政府消息，巴基斯坦总理谢里夫在联合国大会期间，会见了欧洲央行管委科斯塔和欧盟委员会主席冯德莱恩。", "tags": ["环球市场情报"], "id": 256738}, {"src": "cs", "time": "2026-09-24 05:37:33", "ts": "2026-09-24 05:37:33", "content": "当地时间9月23日下午，国家主席习近平抵达华盛顿，开始对美国进行国事访问。 （新华社）", "tags": [], "id": 256737}, {"src": "cs", "time": "2026-09-24 05:22:57", "ts": "2026-09-24 05:22:57", "content": "【联合国秘书长古特雷斯呼吁加快能源转型】联合国秘书长古特雷斯当地时间9月23日在第81届联合国大会高级别周期间举行的气候问题高级别会议上发言指出，全球气候危机正在加速，必须立即采取更有力的行动。古特雷斯呼吁各国加快能源转型，扩大可再生能源使用规模、提高能源效率、减少甲烷排放，逐步摆脱化石燃料。", "tags": ["能源行业新闻", "碳中和期货"], "id": 256736}, {"src": "cs", "time": "2026-09-24 05:16:51", "ts": "2026-09-24 05:16:51", "content": "富时A50期指连续夜盘收跌0.5%，报14462点。", "tags": ["环球市场情报"], "id": 256735}, {"src": "cs", "time": "2026-09-24 05:14:54", "ts": "2026-09-24 05:14:54", "content": "【离岸人民币兑美元较周二纽约尾盘跌127点】周三（9月23日）纽约尾盘（周四北京时间04:59），离岸人民币（CNH）兑美元报6.7115元，较周二纽约尾盘跌127点，日内整体交投于6.6955-6.7142元区间。", "tags": ["人民币大新闻", "外汇期货"], "id": 256734}, {"src": "cs", "time": "2026-09-24 05:07:04", "ts": "2026-09-24 05:07:04", "content": "国际贵金属期货普遍收跌，COMEX黄金期货跌1.23%，报4322.7美元/盎司；COMEX白银期货跌2.4%，报64.93美元/盎司。", "tags": ["期货市场情报", "有色金属", "黄金", "贵金属期货"], "id": 256733}, {"src": "cs", "time": "2026-09-24 05:05:29", "ts": "2026-09-24 05:05:29", "content": "【特朗普总统抵达机场 迎接习近平主席到访】当地时间9月23日下午，国家主席习近平乘专机将抵达美国首都华盛顿。美国总统特朗普来到安德鲁斯空军基地，迎接习近平主席到访。 （央视新闻）", "tags": [], "id": 256732}, {"src": "cs", "time": "2026-09-24 04:51:08", "ts": "2026-09-24 04:51:08", "content": "据报道，OpenAI智能体访问了澳大利亚联邦医疗保险统计数据，这起事件发生于6月。", "tags": ["环球市场情报"], "id": 256731}, {"src": "cs", "time": "2026-09-24 04:38:37", "ts": "2026-09-24 04:38:37", "content": "【发现疑似无人机 德国柏林勃兰登堡机场一度暂停航班起降】德国柏林勃兰登堡机场当地时间9月23日晚因发现疑似无人机，航班起降一度全面暂停，持续约45分钟。当地机场方面及德国联邦警察证实，发现无人机后，北跑道于20时左右首先关闭，20时20分南跑道也停止起降，21时05分解除限制，机场航班运行随后恢复正常。德国联邦警察表示，警方在机场未发现相关无人机，目前也无法确定其具体类型。有消息称，至少有两架航班因此改道。", "tags": ["环球市场情报"], "id": 256730}, {"src": "cs", "time": "2026-09-24 04:11:08", "ts": "2026-09-24 04:11:08", "content": "【英伟达成美国信用违约互换最活跃标的之一 对冲需求飙升】与英伟达挂钩的衍生品如今已成为美国信用违约互换（CDS）市场交易最活跃的品种之一，投资者正积极利用该工具对冲该公司债券的风险敞口。由于市场参与者对英伟达债券的信用保护交易激增，英伟达被纳入CDX投资级指数。过去六个月内，市场参与者交易的信用保护名义本金达69亿美元。在英伟达大举借债以及公司宣布一系列AI相关基础设施交易后，对冲英伟达债券违约的成本今年已翻倍。", "tags": ["环球市场情报", "美股动态"], "id": 256729}, {"src": "cs", "time": "2026-09-24 04:09:04", "ts": "2026-09-24 04:09:04", "content": "美国总统特朗普儿子Trump JR.旗下1789 Capital洽谈融资30亿美元。", "tags": ["环球市场情报"], "id": 256728}], "eastmoney": [{"src": "eastmoney", "time": "2026-09-24 07:43:00", "ts": "2026-09-24 07:43:00", "content": "政策赋能叠加技术迭代 AI教育驶入发展快车道｜【政策赋能叠加技术迭代 AI教育驶入发展快车道】9月23日，国务院新闻办公室举行“开局起步‘十五五’”系列主题新闻发布会，教育部相关负责人表示，“深入推进教育数智化，建强用好国家智慧教育平台，赋能教育教学、科学研究和教育治理，增强师生人工智能素养”。", "important": 0, "vip": 0, "tags": [], "id": "202609243882827493"}, {"src": "eastmoney", "time": "2026-09-24 07:42:00", "ts": "2026-09-24 07:42:00", "content": "非遗传承价值凸显 上市公司探索商业化新路径｜【非遗传承价值凸显 上市公司探索商业化新路径】近日，文化和旅游部印发《非物质文化遗产保护传承“十五五”规划》，其中要求坚持守正创新，加强非遗生活化保护，探索非遗当代表达新方式、合理利用新形式，培育一批非遗传承体验新场景。具体来看，“文旅+非遗”成为众多文旅上市公司的发力方向。", "important": 0, "vip": 0, "tags": [], "id": "202609243882827530"}, {"src": "eastmoney", "time": "2026-09-24 07:41:00", "ts": "2026-09-24 07:41:00", "content": "中信建投：当前全球宏观形势有“五个不确定与五个确定”｜【中信建投：当前全球宏观形势有“五个不确定与五个确定”】中信建投指出，当前全球宏观形势有“五个不确定与五个确定”，主要受AI科技革命、国际货币变革和地缘冲突影响，内核是生产力变革与生产关系调整在全球层面的集中映射。", "important": 0, "vip": 0, "tags": [], "id": "202609243882942577"}, {"src": "eastmoney", "time": "2026-09-24 07:41:00", "ts": "2026-09-24 07:41:00", "content": "拆解证券交易印花税高增长的底层逻辑｜【拆解证券交易印花税高增长的底层逻辑】日前发布的最新税收数据显示，资本市场交易带动证券交易印花税、企业所得税、个人所得税、国内增值税等增长。今年资本市场总体较为活跃，前8个月A股日均股票成交额2.7万亿元，较去年同期增长72.8%，带动相关税种、行业税收较快增长，其中证券交易印花税增长82%。这一积极变化，是资本市场政策端、资产端与资金端协同发力的结果：投融资改革稳定市场预期，优质资产供给增强投资吸引力，财富配置转型拓宽资金来源。", "important": 0, "vip": 0, "tags": [], "id": "202609243882827930"}, {"src": "eastmoney", "time": "2026-09-24 07:40:00", "ts": "2026-09-24 07:40:00", "content": "互联网保险拟设“十不得”划定负面清单｜【互联网保险拟设“十不得”划定负面清单】记者日前从业内获悉，监管部门正就《关于进一步规范互联网保险经营有关事项的通知》向保险公司和中介平台征求意见。为进一步规范互联网保险经营，《通知》从销售行为、产品管理、支付管理以及渠道管理四大方面作出禁止性规定，一共涉及10项具体内容。受访人士认为，《通知》坚持问题导向，明确了经营“十不得”，具有很强的针对性，预计将推动互联网保险进一步规范发展。", "important": 0, "vip": 0, "tags": [], "id": "202609243882828226"}, {"src": "eastmoney", "time": "2026-09-24 07:38:00", "ts": "2026-09-24 07:38:00", "content": "北交所梯度生态助中小企业向上向优｜【北交所梯度生态助中小企业向上向优】2026年以来，北交所上市新股数量已达60只，超过去年全年的26只。在新股数量快速增长的同时，其创新属性也愈发凸显。数据显示，今年北交所新增上市公司中，有48家为国家级专精特新“小巨人”企业，占比达80%。", "important": 0, "vip": 0, "tags": [], "id": "202609243882829449"}, {"src": "eastmoney", "time": "2026-09-24 07:37:12", "ts": "2026-09-24 07:37:12", "content": "Meta推出无摄像头版智能眼镜 引入Muse助手功能｜【Meta推出无摄像头版智能眼镜 引入Muse助手功能】MetaPlatforms正在扩展其智能眼镜产品线，推出无摄像头版本，并将Muse助手功能引入旗下智能眼镜产品。", "important": 0, "vip": 0, "tags": [], "id": "202609243882910941"}, {"src": "eastmoney", "time": "2026-09-24 07:37:00", "ts": "2026-09-24 07:37:00", "content": "一线城市新房成交面积同比增长超10% 楼市“金九”成色向好｜【一线城市新房成交面积同比增长超10% 楼市“金九”成色向好】9月是房地产市场的传统旺季。目前，市场旺季特征已有所显现，重点城市新房、二手房市场活跃度均有提升。从新房市场来看，中指研究院数据显示，截至9月20日，9月重点30城新建商品住宅成交面积同比微增1.4%，一线城市新建商品住宅成交面积同比增长超10%，其中，北京、上海分别同比增长23%和22%。", "important": 0, "vip": 0, "tags": [], "id": "202609243882829650"}, {"src": "eastmoney", "time": "2026-09-24 07:36:00", "ts": "2026-09-24 07:36:00", "content": "以优质体育赛事激发消费活力｜【以优质体育赛事激发消费活力】近期，2026中国网球公开赛、2026年国际篮联洲际杯等多项体育赛事相继开赛，这不仅点燃了大众运动热情，更带动餐饮、文旅、制造等多个领域需求共同释放。赛事经济已然成为扩大内需、推动经济稳定增长的重要抓手。", "important": 0, "vip": 0, "tags": [], "id": "202609243882829795"}, {"src": "eastmoney", "time": "2026-09-24 07:34:44", "ts": "2026-09-24 07:34:44", "content": "Myseum.AI拟申请将纳斯达克上市普通股代币化｜【Myseum.AI拟申请将纳斯达克上市普通股代币化】当地时间9月23日，美国隐私型AI及社交媒体技术公司Myseum.AI宣布，计划向一家或多家合格数字资产证券平台申请，将其纳斯达克上市普通股进行代币化。", "important": 0, "vip": 0, "tags": [], "id": "202609243882896383"}, {"src": "eastmoney", "time": "2026-09-24 07:32:51", "ts": "2026-09-24 07:32:51", "content": "A股限售股解禁一览：9.26亿元市值限售股今日解禁｜【A股限售股解禁一览：9.26亿元市值限售股今日解禁】数据显示，周四（9月24日），共有10家公司限售股解禁，合计解禁量为4829.53万股，按最新收盘价计算，合计解禁市值为9.26亿元。从解禁市值来看，杰华特、陕鼓动力、振华重工解禁市值居前，解禁市值分别为5.42亿元、1.32亿元、9234.88万元。", "important": 0, "vip": 0, "tags": [], "id": "202609243882890729"}, {"src": "eastmoney", "time": "2026-09-24 07:31:50", "ts": "2026-09-24 07:31:50", "content": "Anthropic成立生命科学研究团队 Claude发现具有CRISPR样特征的新型酶系统｜【Anthropic成立生命科学研究团队 Claude发现具有CRISPR样特征的新型酶系统】当地时间9月23日，Anthropic宣布成立生命科学研究团队及实验室，并公布Claude参与生物学研究取得的早期成果。研究人员称，Claude在分析超过20万个逆转录酶（RT）序列后，发现一种此前未被描述的酶系统，并将其命名为“阵列相关逆转录酶”（ART）。", "important": 0, "vip": 0, "tags": [], "id": "202609243882879385"}, {"src": "eastmoney", "time": "2026-09-24 07:31:50", "ts": "2026-09-24 07:31:50", "content": "山东墨龙：拟配售新H股净筹约1.15亿港元 约70%用于偿还借款｜【山东墨龙：拟配售新H股净筹约1.15亿港元 约70%用于偿还借款】9月24日早间，山东墨龙在港交所公告，公司与配售代理于2026年9月24日（交易时段前）订立配售协议，据此，公司同意按配售价发行配售股份，而配售代理同意作为公司的代理，以按尽力基准促使承配人按配售价每股3.50港元购买配售股份。", "important": 0, "vip": 0, "tags": [], "id": "202609243882875570"}, {"src": "eastmoney", "time": "2026-09-24 07:30:07", "ts": "2026-09-24 07:30:07", "content": "“迷你豪宅”火了！房企争夺“迷你宅地”｜【“迷你豪宅”火了！房企争夺“迷你宅地”】近段时间，“迷你宅地”成为土拍市场的绝对焦点。在全国多个重点城市的供地现场，这类小体量地块以低总价、高周转和核心区位优势，频频拍出高溢价。从地块规模维度看，这类地块的出让规划建面通常介于1万平方米至5万平方米之间，部分核心城区的“迷你宅地”规模甚至不足1万平方米。而“迷你豪宅”的快速兴起，正是土拍端。", "important": 0, "vip": 0, "tags": [], "id": "202609233882577739"}, {"src": "eastmoney", "time": "2026-09-24 07:28:42", "ts": "2026-09-24 07:28:42", "content": "矢量网络分析仪概念突然火了！龙头暴涨近70%（附股）｜【矢量网络分析仪概念突然火了！龙头暴涨近70%（附股）】9月23日，VNA概念股集体逆市大涨，其中，优利德、普源精电20%涨停，电科思仪、创远信科涨超10%，东方中科10%涨停，鼎阳科技、坤恒顺维、同惠电子涨超9%。其中，龙头鼎阳科技自9月16日启动以来，累计涨幅近70%。VNA概念股大涨，源于有消息称目前高频高速矢量网络分析仪已出现供货紧张。", "important": 0, "vip": 0, "tags": [], "id": "202609243882872313"}, {"src": "eastmoney", "time": "2026-09-24 07:27:20", "ts": "2026-09-24 07:27:20", "content": "红利ETF失宠成长方向吸金 市场风格再平衡进入后半程｜【红利ETF失宠成长方向吸金 市场风格再平衡进入后半程】市场的风，又开始悄悄变了。一边是前段时间还风头正盛的红利资产，近期却突然有些“失宠”，不少资金悄然撤离红利类ETF；另一边是成长方向重新活跃，医药、科技、周期等多个赛道轮番接力。资金不再只围着一条主线转，市场的赚钱地图正在重新铺开。这究竟意味着红利行情要告一段落，还是风格再平衡进入了新的阶段？从ETF申赎到基金净值变化，一场新的资金迁徙已经悄然展开。", "important": 0, "vip": 0, "tags": [], "id": "202609243882834019"}, {"src": "eastmoney", "time": "2026-09-24 07:26:55", "ts": "2026-09-24 07:26:55", "content": "高通拟收购机器人软件公司PickNik 加强开源机器人及实体AI布局｜【高通拟收购机器人软件公司PickNik 加强开源机器人及实体AI布局】当地时间9月23日，高通宣布已与机器人软件公司PickNik达成收购协议，交易完成仍需满足惯例交割条件。PickNik长期维护开源机器人操作框架MoveIt，该框架基于机器人操作系统（ROS），广泛用于工业自动化、服务机器人及实体AI等领域。高通表示，收购后MoveIt将继续保持开源，并支持第三方硬件平台，同时加强与高通Dragonwing机器人平台的整合。", "important": 0, "vip": 0, "tags": [], "id": "202609243882872418"}, {"src": "eastmoney", "time": "2026-09-24 07:26:25", "ts": "2026-09-24 07:26:25", "content": "大幅放宽申购限制 科技主题基金集体“松绑”｜【大幅放宽申购限制 科技主题基金集体“松绑”】7月以来，主动权益基金“松绑”渐成趋势。多只科技主题基金相继放宽大额申购限制，显示出基金经理在当前市场点位下对后市信心的修复以及对资金流入持欢迎态度。尤其是在科技板块经历调整、估值有所消化之后，部分基金经理判断结构性机会正在显现，此时放松限购既是对自身持仓信心的体现，也是为后续布局储备弹药。", "important": 0, "vip": 0, "tags": [], "id": "202609243882833114"}, {"src": "eastmoney", "time": "2026-09-24 07:25:27", "ts": "2026-09-24 07:25:27", "content": "时报观察 | 民企五百强“含新量”跃升 科技产业增长极加速成形｜【时报观察 | 民企五百强“含新量”跃升 科技产业增长极加速成形】全国工商联近日发布“2026中国民营企业500强”及相关调研分析报告。细读榜单，一组此消彼长的数据值得关注：制造业上榜企业数量占比升至70.6%，营收与研发费用贡献均超过七成；反观房地产、房屋建筑业，相较于2021年的70余家，最新上榜企业数量大幅收缩。一升一降之间，赛道切换的信号已相当明确，榜单的“含新量”大幅提升，“含房量”明显下降。", "important": 0, "vip": 0, "tags": [], "id": "202609243882832710"}, {"src": "eastmoney", "time": "2026-09-24 07:24:01", "ts": "2026-09-24 07:24:01", "content": "谷歌推出Gemini 3.8 Flash TTS及Flash-Lite TTS 支持自定义AI声音｜【谷歌推出Gemini 3.8 Flash TTS及Flash-Lite TTS 支持自定义AI声音】当地时间9月23日，谷歌宣布推出Gemini3.8FlashTTS和Gemini3.8Flash-LiteTTS两款文本转语音模型。前者面向声音和角色设计，支持通过自然语言创建定制声音，并逐句控制语气、语速、口音等；后者面向大规模音频生成和配音场景。谷歌称，两款模型支持超过100种语言和方言，并提供2000多种可直接使用的声音。FlashTTS还支持基于30秒音频样本复制声音。", "important": 0, "vip": 0, "tags": [], "id": "202609243882871641"}, {"src": "eastmoney", "time": "2026-09-24 07:22:36", "ts": "2026-09-24 07:22:36", "content": "并购重组“工具箱”持续扩容 从“能用”走向“好用”成政策引导重点｜【并购重组“工具箱”持续扩容 从“能用”走向“好用”成政策引导重点】分期支付、定向可转债、差异化定价、简易审核、锁定期“反向挂钩”……随着并购重组工具箱持续扩容，A股并购重组的架构和效率正在发生积极变化。专家表示，监管思路由审批导向转向交易导向，是本轮并购重组制度创新的一大亮点。工具箱已基本补齐，在解决“能不能做”后，如何让工具“好用、想用”，成为并购市场的下一道考题。", "important": 0, "vip": 0, "tags": [], "id": "202609243882832690"}, {"src": "eastmoney", "time": "2026-09-24 07:20:14", "ts": "2026-09-24 07:20:14", "content": "AI+机器人 小场景跑出大订单 具身智能落地走向实处｜【AI+机器人 小场景跑出大订单 具身智能落地走向实处】9月23日11时，第五届全球数字贸易博览会人工智能展区，杭州星物种机器人有限公司展台上的一台清洁机器人正在模拟公共卫生间作业，引来一些海外客商驻足。“今年数贸会刚刚开始，我们就收到了超过500台意向订单。”星物种机器人联合创始人、COO余济萍告诉上海证券报记者，上述意向订单主要来自海外。", "important": 0, "vip": 0, "tags": [], "id": "202609243882835347"}, {"src": "eastmoney", "time": "2026-09-24 07:20:01", "ts": "2026-09-24 07:20:01", "content": "*ST康佳A：公司已正式进入主动终止上市办理流程｜【*ST康佳A：公司已正式进入主动终止上市办理流程】9月23日晚间，*ST康佳A公告，公司拟以股东会决议方式主动撤回A股和B股股票在深交所的上市交易，并在股票终止上市后申请转入全国中小企业股份转让系统有限责任公司代为管理的退市板块转让。本次终止上市事项已于2026年9月14日经公司2026年第二次临时股东会审议通过。", "important": 0, "vip": 0, "tags": [], "id": "202609243882870653"}, {"src": "eastmoney", "time": "2026-09-24 07:18:01", "ts": "2026-09-24 07:18:01", "content": "微软计划2030年前向中东投资超100亿美元 加强AI基础设施建设｜【微软计划2030年前向中东投资超100亿美元 加强AI基础设施建设】当地时间9月23日，微软宣布将在2030年前向中东地区投入超过100亿美元资本及运营支出，重点扩大云计算和AI基础设施，并加强在科威特、卡塔尔、沙特阿拉伯和阿联酋的合作。", "important": 0, "vip": 0, "tags": [], "id": "202609243882870331"}, {"src": "eastmoney", "time": "2026-09-24 07:18:01", "ts": "2026-09-24 07:18:01", "content": "真兰仪表：拟8000万元-1.6亿元回购公司股份｜【真兰仪表：拟8000万元-1.6亿元回购公司股份】真兰仪表9月23日晚间公告，拟以集中竞价交易方式回购公司股份，回购总金额不低于8000万元且不超过1.6亿元。回购价格不超过20元/股。", "important": 0, "vip": 0, "tags": [], "id": "202609243882870123"}, {"src": "eastmoney", "time": "2026-09-24 07:18:01", "ts": "2026-09-24 07:18:01", "content": "宁波东力：控股股东拟增持1亿元-2亿元公司股份｜【宁波东力：控股股东拟增持1亿元-2亿元公司股份】宁波东力9月23日晚间公告，公司控股股东东力控股集团有限公司计划自本公告披露之日起6个月内，通过深圳证券交易所交易系统以集中竞价方式增持公司股份，拟增持金额不低于1亿元且不高于2亿元，增持比例不超过公司总股本的2%。本次增持不设价格区间。", "important": 0, "vip": 0, "tags": [], "id": "202609243882869827"}, {"src": "eastmoney", "time": "2026-09-24 07:17:45", "ts": "2026-09-24 07:17:45", "content": "扎克伯格：预计将通过从每笔交易中收取少量手续费来从Muse获得收益｜Meta首席执行官扎克伯格表示，公司预计将通过从每笔交易中收取少量手续费来从Muse获得收益。", "important": 0, "vip": 0, "tags": [], "id": "202609243882870465"}, {"src": "eastmoney", "time": "2026-09-24 07:16:01", "ts": "2026-09-24 07:16:01", "content": "运机集团：拟1亿元-2亿元回购公司股份｜【运机集团：拟1亿元-2亿元回购公司股份】运机集团9月23日晚间公告，拟以集中竞价交易方式回购公司股份，回购总金额不低于1亿元且不超过2亿元。回购价格不超过40元/股。回购股份将用于股权激励或员工持股计划。回购期限为自董事会审议通过回购股份方案之日起12个月内。", "important": 0, "vip": 0, "tags": [], "id": "202609243882869437"}, {"src": "eastmoney", "time": "2026-09-24 07:15:21", "ts": "2026-09-24 07:15:21", "content": "Meta Platforms：正在为Muse增加计算机操作功能｜MetaPlatforms高管称，公司正在为Muse增加计算机操作功能。", "important": 0, "vip": 0, "tags": [], "id": "202609243882869560"}, {"src": "eastmoney", "time": "2026-09-24 07:14:01", "ts": "2026-09-24 07:14:01", "content": "阳光资产获批变更业务范围｜【阳光资产获批变更业务范围】9月23日，国家金融监督管理总局网站发布批复，同意阳光资产管理股份有限公司业务范围变更。", "important": 0, "vip": 0, "tags": [], "id": "202609243882868483"}, {"src": "eastmoney", "time": "2026-09-24 07:12:01", "ts": "2026-09-24 07:12:01", "content": "美国财政部将回购最多60亿美元长期国债｜【美国财政部将回购最多60亿美元长期国债】当地时间9月23日，美国财政部发布初步公告，计划于9月24日开展国债回购操作，拟回购面值最高60亿美元的长期国债，初步适用到期日范围为2046年11月15日至2056年8月15日。", "important": 0, "vip": 0, "tags": [], "id": "202609243882868179"}, {"src": "eastmoney", "time": "2026-09-24 07:11:23", "ts": "2026-09-24 07:11:23", "content": "私募业规模连续11个月创新高｜【私募业规模连续11个月创新高】中国证券投资基金业协会（简称“中基协”）最新披露的数据显示，截至8月末，存续私募基金规模为25.75万亿元，相较于7月末小幅提升。至此，私募业管理规模已经连续11个月刷新历史纪录。", "important": 0, "vip": 0, "tags": [], "id": "202609243882863076"}, {"src": "eastmoney", "time": "2026-09-24 07:10:00", "ts": "2026-09-24 07:10:00", "content": "C沈鼓何以变“神鼓”？｜【C沈鼓何以变“神鼓”？】在这场击鼓传花的游戏中，敲的是“神鼓”，赌的是暴利。过去几天，发行价不过4.39元的C沈鼓，被炒作资金一路拉涨至82.39元，区间最大涨幅逼近18倍。这期间，上市初期有限的筹码不停流转，公司股票盘中六次触发临时停牌，连续三个交易日换手率超过70%。不过，鼓声终有停歇的时候。", "important": 0, "vip": 0, "tags": [], "id": "202609243882865718"}, {"src": "eastmoney", "time": "2026-09-24 07:09:10", "ts": "2026-09-24 07:09:10", "content": "AI巨头联合国发声：警惕人工智能对潜在风险｜【AI巨头联合国发声：警惕人工智能对潜在风险】周三，全球头部人工智能企业在联合国安理会呼吁各国政府协同治理这项能力持续增强的技术。Anthropic首席执行官达里奥·阿莫迪表示，如果治理失当，人工智能可能对全人类构成风险。当前已有预警：AI系统很快将实现自我迭代，甚至脱离人类管控。OpenAI首席执行官山姆·奥特曼主张国际合作，AI最重要的决策不能仅由旧金山的实验室做出。", "important": 0, "vip": 0, "tags": [], "id": "202609243882867332"}, {"src": "eastmoney", "time": "2026-09-24 07:08:01", "ts": "2026-09-24 07:08:01", "content": "无锡落地2026年首笔新型政策性金融工具借款 专项投资于华虹FAB9B项目建设｜【无锡落地2026年首笔新型政策性金融工具借款 专项投资于华虹FAB9B项目建设】无锡市高新区创业投资控股集团有限公司于近日获得国家开发银行新型政策性金融工具支持，落地资金25.36亿元，专项投资于华虹FAB9B项目建设。该笔资金是无锡市落地的2026年首笔新型政策性金融工具借款。华虹三期项目作为无锡高新区的标志性工程，规划建设月产能5.5万片的12英寸特色工艺晶圆代工产线，聚焦功率器件、模拟芯片、嵌入式存储等细分赛道。", "important": 0, "vip": 0, "tags": [], "id": "202609243882867242"}, {"src": "eastmoney", "time": "2026-09-24 07:05:03", "ts": "2026-09-24 07:05:03", "content": "软银将发行约111亿美元的优先票据｜软银将发行约111亿美元的优先票据，到期日为2030年至2034年。", "important": 0, "vip": 0, "tags": [], "id": "202609243882867159"}, {"src": "eastmoney", "time": "2026-09-24 07:03:20", "ts": "2026-09-24 07:03:20", "content": "科学家直接捕捉到系外行星射电信号｜【科学家直接捕捉到系外行星射电信号】宇宙深处，一束微弱无线电波穿过约64光年时空。美国哈佛—史密森天体物理中心的科学家利用位于南非的MeerKAT射电望远镜，观测了βPictoris行星系统，捕捉到来自其巨行星βPictorisb的射电信号。这可能是人类首次明确探测到来自系外行星的射电信号，有助于检验行星内部理论模型。", "important": 0, "vip": 0, "tags": [], "id": "202609243882867068"}, {"src": "eastmoney", "time": "2026-09-24 06:56:58", "ts": "2026-09-24 06:56:58", "content": "澳大利亚三年期国债收益率涨14个基点 创2011年以来新高｜澳大利亚三年期国债收益率涨14个基点，创2011年以来新高。", "important": 0, "vip": 0, "tags": [], "id": "202609243882863168"}, {"src": "eastmoney", "time": "2026-09-24 06:52:32", "ts": "2026-09-24 06:52:32", "content": "日本一客机因发动机机油温度过高警报折返｜【日本一客机因发动机机油温度过高警报折返】据日本全日空航空公司方面消息，当地时间23日，该公司一架客机从那霸机场起飞后，因发动机机油温度过高警报折返。这架客机于当地时间21时左右起飞，原计划飞往佐贺机场。22时左右，该客机返回那霸机场后停在滑行道上，使用紧急逃生梯疏散乘客下机。目前暂无人员受伤报告。调查正在进行中。", "important": 0, "vip": 0, "tags": [], "id": "202609243882862188"}, {"src": "eastmoney", "time": "2026-09-24 06:50:04", "ts": "2026-09-24 06:50:04", "content": "MLF+隔夜逆回购 央行双管齐下呵护流动性｜【MLF+隔夜逆回购 央行双管齐下呵护流动性】中国人民银行9月23日消息，为保持银行体系流动性充裕，9月24日，央行将以固定数量、利率招标、多重价位中标方式开展8000亿元中期借贷便利（MLF）操作，期限为1年期。", "important": 0, "vip": 0, "tags": [], "id": "202609243882861260"}], "sina": [{"src": "sina", "time": "2026-09-24 07:44:44", "ts": "2026-09-24 07:44:44", "content": "【委内瑞拉代总统罗德里格斯提议委内瑞拉举行选举，称重建工作尚需时日】委内瑞拉代总统德尔西・罗德里格斯周三在联合国大会发言，谈及选举、国际关系以及民主转型事宜。罗德里格斯没有给出选举时间表，表示国家需要先开展重建。她称，国家重建需要时间，前路并不平坦。罗德里格斯呼吁建立相互尊重的国际关系，并表示 2026 年委内瑞拉在政治上遭到 “扼制”。她盛赞与美国达成的协议为史上规模最大的协议之一，称该协议有助于保障全球能源平衡。", "important": 0, "vip": 0, "tags": [], "id": "sina5110683"}, {"src": "sina", "time": "2026-09-24 07:43:32", "ts": "2026-09-24 07:43:32", "content": "META表示，META VR眼镜起售价为1,299美元。", "important": 0, "vip": 0, "tags": [], "id": "sina5110682"}, {"src": "sina", "time": "2026-09-24 07:43:16", "ts": "2026-09-24 07:43:16", "content": "【台积电据报明年1月起上调晶圆代工报价，涨幅约3%至6%】9月24日消息，据报道，供应链人士透露，台积电预计自2027年1月起调整晶圆出厂价格，涨幅约3%至6%，其中2纳米、3纳米等先进制程涨幅较高；成熟及特殊制程则将根据产品、产能利用率和客户情况分别议价。报道指出，若调价落地，苹果芯片采购成本可能增加，叠加市场此前关于苹果接受三星电子明年第一季度上调内存报价的消息，iPhone明年是否涨价再度受到关注。台积电回应称，公司不评论价格问题，定价策略始终以策略为导向，并将持续与客户合作提供价值。", "important": 0, "vip": 0, "tags": [], "id": "sina5110681"}, {"src": "sina", "time": "2026-09-24 07:42:17", "ts": "2026-09-24 07:42:17", "content": "META宣布推出META VR眼镜。", "important": 0, "vip": 0, "tags": [], "id": "sina5110679"}, {"src": "sina", "time": "2026-09-24 07:41:06", "ts": "2026-09-24 07:41:06", "content": "META：RAY-BAN Meta智能音频眼镜将于10月13日出货，售价349美元，现已开启预订。RAY-BAN META（第三代）今日上市，起售价449美元。", "important": 0, "vip": 0, "tags": [], "id": "sina5110678"}, {"src": "sina", "time": "2026-09-24 07:40:55", "ts": "2026-09-24 07:40:55", "content": "【中信建投：当前全球宏观形势有“五个不确定与五个确定”】中信建投指出，当前全球宏观形势有“五个不确定与五个确定”，主要受AI科技革命、国际货币变革和地缘冲突影响，内核是生产力变革与生产关系调整在全球层面的集中映射。“五个不确定”分别是：一是美联储的货币政策路径不确定，二是发达经济体的高债务能否持续不确定，三是日元的汇率及全球套利机制不确定，四是原油的地缘冲击与供给安全不确定，五是AI时代的长期全球宏观影响不确定。“五个确定”分别是：一是发达经济体的通胀刚性是确定的，二是发达经济体债务压力与通胀催生的收益率上行是确定的，三是我国进出口高增与制造业升级是确定的，四是我国保持政策定力、高质量发展与科技进步是确定的，五是人民币升值、人民币资产重估与投资中国是确定的。", "important": 0, "vip": 0, "tags": [], "id": "sina5110677"}, {"src": "sina", "time": "2026-09-24 07:40:01", "ts": "2026-09-24 07:40:01", "content": "【新股提示：粤芯半导体今日申购】今日可申购创业板粤芯半导体。粤芯半导体发行总数512646000股，发行市盈率--倍，申购代码为：301660，申购价格：12.01元，申购上限128000股。", "important": 0, "vip": 0, "tags": [], "id": "sina5110676"}, {"src": "sina", "time": "2026-09-24 07:39:43", "ts": "2026-09-24 07:39:43", "content": "【图恩计划再度竞选党魁，美参议院共和党竭力保住席位】参议院多数党领袖约翰・图恩周三在国会办公室接受媒体采访时表示，即便共和党失去参议院多数席位，他仍计划再度参选共和党领袖。来自南达科他州的共和党参议员图恩，为党内同僚提供较大操作空间与大量资金，力求保住共和党对参议院的控制权。图恩称：“在很多方面，参议院就是一道防火墙。”他表示：“如果众议院控制权易手，接下来两年我们可能会忙于弹劾或各类调查等事务。否则，参议院将重点处理司法及行政官员提名。”", "important": 0, "vip": 0, "tags": [], "id": "sina5110675"}, {"src": "sina", "time": "2026-09-24 07:38:18", "ts": "2026-09-24 07:38:18", "content": "【供应充足、价格稳定 双节假期“菜篮子”有保障】农业农村部最新农情调度显示，目前，全国蔬菜在田面积1.08亿亩，9月中旬产量达2700万吨以上，能够满足中秋等节日消费需求。", "important": 0, "vip": 0, "tags": [], "id": "sina5110674"}, {"src": "sina", "time": "2026-09-24 07:37:36", "ts": "2026-09-24 07:37:36", "content": "据报道，图恩将寻求连任美国参议院共和党领袖。", "important": 0, "vip": 0, "tags": [], "id": "sina5110673"}, {"src": "sina", "time": "2026-09-24 07:36:49", "ts": "2026-09-24 07:36:49", "content": "META表示，探险者款智能眼镜起售价为249美元。", "important": 0, "vip": 0, "tags": [], "id": "sina5110672"}, {"src": "sina", "time": "2026-09-24 07:36:34", "ts": "2026-09-24 07:36:34", "content": "【美国将为阿根廷关键矿产与能源项目提供70亿美元资金】美国驻阿根廷大使彼得・拉梅拉斯（ Peter Lamelas）在X平台宣布，美国进出口银行将为阿根廷的关键矿产和能源项目提供最高70亿美元融资。拉梅拉斯补充称，该资金将支持互惠项目，打造具备战略安全性的能源产业链。拉梅拉斯附上的声明显示，阿根廷与美国启动安第斯-大西洋走廊计划，吸引公私资本投入交通、能源与数字基础设施建设。声明提到：“依托美国及美方支持的铁路、水道、港口、管道、能源生产与输电基础设施投资，矿产、石油和天然气出口规模将会扩大。”这份联合声明由两国政府在纽约联合国大会期间发布。", "important": 0, "vip": 0, "tags": [], "id": "sina5110671"}, {"src": "sina", "time": "2026-09-24 07:35:38", "ts": "2026-09-24 07:35:38", "content": "【Anthropic成立生命科学研究团队，Claude发现具有CRISPR样特征的新型酶系统】当地时间9月23日，Anthropic宣布成立生命科学研究团队及实验室，并公布Claude参与生物学研究取得的早期成果。研究人员称，Claude在分析超过20万个逆转录酶（RT）序列后，发现一种此前未被描述的酶系统，并将其命名为“阵列相关逆转录酶”（ART）。Anthropic称，Claude约950个智能体在21小时内使用约2.1亿个Token，筛选出3500个候选系统并进一步缩小至20个。ART主要存在于感染细菌的噬菌体中，由逆转录酶、邻近的辅助基因以及一组排列规律的DNA重复序列组成，后者与CRISPR重复序列具有相似特征。初步实验显示，这些重复序列也会被转录为多个短RNA，但其具体功能仍有待进一步研究。该研究由Anthropic科学家进行实验验证，公司已发布预印本。", "important": 0, "vip": 0, "tags": [], "id": "sina5110670"}, {"src": "sina", "time": "2026-09-24 07:35:34", "ts": "2026-09-24 07:35:34", "content": "【Myseum.AI拟申请将纳斯达克上市普通股代币化】当地时间9月23日，美国隐私型AI及社交媒体技术公司Myseum.AI宣布，计划向一家或多家合格数字资产证券平台申请，将其纳斯达克上市普通股进行代币化。公司称，拟探索由发行人授权的区块链结构，使代币化股票代表公司实际登记的普通股，而非合成敞口，并保留传统股票对应的经济、投票等股东权利。该计划目前不会改变公司现有资本结构或发行新证券，股票仍将以“MYSE”代码在纳斯达克资本市场交易。Myseum.AI表示，代币化仍需经过平台及监管机构批准，公司目前正评估相关区块链网络、经纪交易商、托管机构和其他数字证券基础设施提供商，不能保证最终获批或实现代币化交易。", "important": 0, "vip": 0, "tags": [], "id": "sina5110669"}, {"src": "sina", "time": "2026-09-24 07:34:30", "ts": "2026-09-24 07:34:30", "content": "META发布第三代RAY-BAN智能眼镜。", "important": 0, "vip": 0, "tags": [], "id": "sina5110668"}, {"src": "sina", "time": "2026-09-24 07:33:51", "ts": "2026-09-24 07:33:51", "content": "【油价高位回调 化工品价格近日整体走弱】在9月15日触及历史高位后，近日来国内原油期货价格持续回调，主力合约2611已跌破700元/桶关口。9月23日盘中，原油期货主力合约2611最低触及680元/桶，单日跌超4%，较前期高点已跌超20%。国际市场方面，WTI原油价格已跌破90美元/桶。在油价弱势运行背景下，前期大涨的化工品近日整体回调。9月23日，主力合约中沥青收跌4.61%，乙二醇跌3.82%，短纤、甲醇均跌超3%。不过，当前部分上游化工品价格依然处于相对高位，对下游产成品成本形成压力，能化产业链生产企业盈利情况分化。", "important": 0, "vip": 0, "tags": [], "id": "sina5110667"}, {"src": "sina", "time": "2026-09-24 07:33:46", "ts": "2026-09-24 07:33:46", "content": "【公募秋季策略会密集召开，积极看多权益资产】金秋布局正当时，公募基金开启“秋播”窗口。近期，华宝基金、建信基金、汇丰晋信基金、富国基金等多家基金公司举行秋季投资策略会，研判后市投资机遇。综合来看，机构普遍看好权益资产配置价值，认为有较多投资机会可以把握。从投资方向看，AI依然是重要的投资主线。（上海证券报）", "important": 0, "vip": 0, "tags": [], "id": "sina5110666"}, {"src": "sina", "time": "2026-09-24 07:33:32", "ts": "2026-09-24 07:33:32", "content": "委内瑞拉代总统罗德里格斯：委内瑞拉重建需要时间，道路并不平坦。", "important": 0, "vip": 0, "tags": [], "id": "sina5110665"}, {"src": "sina", "time": "2026-09-24 07:33:10", "ts": "2026-09-24 07:33:10", "content": "日经指数期货在新加坡交易所开盘下跌835点，报65915点。", "important": 0, "vip": 0, "tags": [], "id": "sina5110664"}, {"src": "sina", "time": "2026-09-24 07:32:46", "ts": "2026-09-24 07:32:46", "content": "Meta宣布推出不带摄像头的智能眼镜。", "important": 0, "vip": 0, "tags": [], "id": "sina5110663"}, {"src": "sina", "time": "2026-09-24 07:32:22", "ts": "2026-09-24 07:32:22", "content": "【新西兰将地方议会合并进程推迟至2027年】新西兰地方政府部长西蒙·沃茨在一份电子邮件声明中表示，新西兰政府已暂停推进地方议会合并的计划，要求官员们做更多工作，以便在 2027 年审议这些提案。政府表示，在要求各地方议会提交各自的重组方案后，共收到了18份合并提案。“在考虑了这些提议之后，内阁还需要做更多工作才能做出最终决定。”", "important": 0, "vip": 0, "tags": [], "id": "sina5110662"}, {"src": "sina", "time": "2026-09-24 07:31:25", "ts": "2026-09-24 07:31:25", "content": "【山东墨龙：拟配售新H股净筹约1.15亿港元，约70%用于偿还借款】9月24日早间，山东墨龙在港交所公告，公司与配售代理于2026年9月24日（交易时段前）订立配售协议，据此，公司同意按配售价发行配售股份，而配售代理同意作为公司的代理，以按尽力基准促使承配人按配售价每股3.50港元购买配售股份。配售股份将根据一般授权配发及发行。假设所有配售股份悉数获配售，配售事项所得款项总额预计为约1.1765亿港元，而配售事项所得款项净额总额预计为约1.1489亿港元。公司拟将配售事项所得款项净额用于以下用途：约70%用于偿还借款；约20%用于结付日常业务营运产生的应付款项，包括采购原材料的付款；约10%用于营运资金及一般企业用途。", "important": 0, "vip": 0, "tags": [], "id": "sina5110661"}, {"src": "sina", "time": "2026-09-24 07:31:03", "ts": "2026-09-24 07:31:03", "content": "【9月银行理财规模延续高增态势 含权类产品为扩容主力】据上海证券报，继8月银行理财规模高增后，记者从业内获取的最新数据显示，9月以来这一态势仍在延续。从增量结构看，含权类产品是本轮理财规模增长的重要增量来源。不过，规模持续攀高，并未为理财公司带来明显的赚钱效应。业内人士对记者表示，规模增长要想真正转化为盈利增长，还有待机构提升投研、产品和风险管理能力。展望后市，银行理财市场能否保持扩容，既取决于资金端的需求变化，也取决于资产端的承接能力。在具体策略上，“控波动，控回撤”已成为不少机构的共同目标。除此之外，投资者预期管理同样重要。", "important": 0, "vip": 0, "tags": [], "id": "sina5110660"}, {"src": "sina", "time": "2026-09-24 07:30:17", "ts": "2026-09-24 07:30:17", "content": "【机构：市场反弹的持续性仍然可期】展望后市，东方证券研报表示，中秋、国庆假期渐近，短期行业轮动加快，市场短期情绪抬升，中期不确定性趋于平稳，整体风险可控，指数或维持震荡格局。 市场风格上，国海证券策略团队发布观点称，未来1个月，市场有望延续反弹，但行业轮动速度依然可能会很快，仍然建议重视拥挤度指标。 华宝证券研报分析称，从量能来看，市场活跃度从低位修复，科技方向有望企稳反弹，但考虑到长假临近，部分资金持币过节对市场反弹高度形成制约，反弹空间或待节后打开。 国金证券策略团队认为，配置上建议关注三大方向：一是有色金属，例如金、铜、铝，在加息预期落地与地缘冲突缓和后，机会已经出现；二是油价下跌反而可能释放全球对能源的补库需求，石油、油运和炼化为代表的能化链条将继续受益；三是科技链上部分供需紧缺且存在技术迭代的环节，推荐光模块、电子布、MLCC、存储等方向。（上海证券报）", "important": 0, "vip": 0, "tags": [], "id": "sina5110659"}, {"src": "sina", "time": "2026-09-24 07:29:54", "ts": "2026-09-24 07:29:54", "content": "【美参议员：特朗普拟以太阳能项目许可换取法案谈判】参议院一位资深谈判代表表示，特朗普政府官员提议批准搁置中的太阳能与风电项目，以此作为与民主党谈判法案的筹码，该法案旨在整体加快能源项目审批流程。参议院环境委员会首席民主党参议员谢尔顿・怀特豪斯周三在华盛顿对记者表示，他正在要求白宫进一步明确这项提议。一位不愿具名的知情人士称，特朗普政府计划在约 300 个等待国防部审批的风电项目中，放行其中 30 个。相关讨论仍属私下磋商。白宫暂未回应置评请求。参议院民主党与共和党谈判代表若达成协议，对油气行业而言将是重大利好。长期以来，油气行业一直希望加快联邦层面审批，缩减环境审查流程；这类审查往往造成项目数年延期，并产生数亿美元额外成本。这项协议同样会惠及可再生能源行业。该行业希望加快新建输电线路的审批，以便将偏远风电场和光伏电站的电力输送至城市与工业用户。尽管如此，政府的提议仅能覆盖特朗普第二任期内被叫停的可再生能源项目中的一小部分。面对政府的反对以及总统下达的暂停令，部分开发商已经撤出海上风电投资。", "important": 0, "vip": 0, "tags": [], "id": "sina5110658"}, {"src": "sina", "time": "2026-09-24 07:29:05", "ts": "2026-09-24 07:29:05", "content": "【谷歌推出Gemini 3.8 Flash TTS及Flash-Lite TTS，支持自定义AI声音】当地时间9月23日，谷歌宣布推出Gemini 3.8 Flash TTS和Gemini 3.8 Flash-Lite TTS两款文本转语音模型。前者面向声音和角色设计，支持通过自然语言创建定制声音，并逐句控制语气、语速、口音等；后者面向大规模音频生成和配音场景。谷歌称，两款模型支持超过100种语言和方言，并提供2000多种可直接使用的声音。Flash TTS还支持基于30秒音频样本复制声音。", "important": 0, "vip": 0, "tags": [], "id": "sina5110657"}, {"src": "sina", "time": "2026-09-24 07:28:50", "ts": "2026-09-24 07:28:50", "content": "【AI算力与新硬件布局落地 消费电子业绩持续兑现】AI算力建设提速叠加AI端侧硬件迭代，正持续打开消费电子行业增长空间。近期，从多家A股消费电子公司半年度业绩说明会释放的信息来看，行业正逐步摆脱手机、PC等传统业务依赖，加速向AI算力、机器人、AI眼镜等赛道布局。算力赛道上，多家公司借技术攻坚、扩产及并购，加码算力整机、液冷散热等核心环节，多款产品预计下半年批量生产。此外，依托精密制造的优势，不少公司加码布局折叠屏材料、AI可穿戴、汽车电子、机器人零部件等新业务，多线培育增长新动能，并有望持续兑现业绩。（上海证券报）", "important": 0, "vip": 0, "tags": [], "id": "sina5110656"}, {"src": "sina", "time": "2026-09-24 07:27:11", "ts": "2026-09-24 07:27:11", "content": "【科技巨头抢滩药物研发 AI制药进入跨界竞合阶段】科技巨头正把AI制药从模型竞赛推向闭环竞赛。近期，Anthropic、字节跳动等加码AI制药领域。例如：Anthropic已在美国旧金山湾区建成湿实验室；字节跳动旗下AI制药公司Anew Labs（新生实验室）以独立公司身份完成首轮外部融资，规模达2.9亿美元；礼来旗下AI制药平台Lilly TuneLab牵手金斯瑞、Twist、Ginkgo，完善AI成药性预测验证链条……记者采访多家AI制药上市公司高管及业内人士了解到，AI制药领域的竞争焦点正转向“谁能建设行业系统性基础设施”，率先跑通“数据—模型—实验—再数据”的完整闭环。与之相伴，产业分工正从单打独斗走向生态竞合。（上海证券报）", "important": 0, "vip": 0, "tags": [], "id": "sina5110655"}, {"src": "sina", "time": "2026-09-24 07:27:06", "ts": "2026-09-24 07:27:06", "content": "委内瑞拉代理总统罗德里格斯：将举行选举。已与反对党开启对话。", "important": 0, "vip": 0, "tags": [], "id": "sina5110654"}, {"src": "sina", "time": "2026-09-24 07:26:53", "ts": "2026-09-24 07:26:53", "content": "Meta宣布推出智能眼镜隐私处理方案。", "important": 0, "vip": 0, "tags": [], "id": "sina5110653"}, {"src": "sina", "time": "2026-09-24 07:26:40", "ts": "2026-09-24 07:26:40", "content": "【汇丰因安全顾虑将本月董事会会议地点从迪拜改成伦敦】据英国《金融时报》援引知情人士报道，出于安全考虑，汇丰将原定于本月在迪拜举行的董事会会议改在伦敦举行。该决定是在与提出了安全关切的汇丰迪拜员工讨论后作出的。汇丰不予置评。", "important": 0, "vip": 0, "tags": [], "id": "sina5110652"}, {"src": "sina", "time": "2026-09-24 07:26:14", "ts": "2026-09-24 07:26:14", "content": "【高通拟收购机器人软件公司PickNik，加强开源机器人及实体AI布局】当地时间9月23日，高通宣布已与机器人软件公司PickNik达成收购协议，交易完成仍需满足惯例交割条件。PickNik长期维护开源机器人操作框架MoveIt，该框架基于机器人操作系统（ROS），广泛用于工业自动化、服务机器人及实体AI等领域。高通表示，收购后MoveIt将继续保持开源，并支持第三方硬件平台，同时加强与高通Dragonwing机器人平台的整合。双方还计划将MoveIt与Arduino VENTUNO Q开发板结合，以降低机器人开发门槛。", "important": 0, "vip": 0, "tags": [], "id": "sina5110651"}, {"src": "sina", "time": "2026-09-24 07:25:12", "ts": "2026-09-24 07:25:12", "content": "阿根廷和美国启动安第斯-大西洋经济走廊。", "important": 0, "vip": 0, "tags": [], "id": "sina5110650"}, {"src": "sina", "time": "2026-09-24 07:25:01", "ts": "2026-09-24 07:25:01", "content": "【加仓意愿再度集聚 股票私募仓位两周连涨】近日，私募基金加仓态势明显。私募排排网数据显示，截至9月18日，股票私募仓位指数（有业绩记录的主观多头股票策略私募产品平均仓位水平）连续两周上涨。从结构来看，截至9月18日，仓位超过八成的私募占比高达67%以上。在业内人士看来，经过前段时间的估值消化，市场结构性行情大概率将转向盈利兑现方向，投资机会或进一步扩散。（上海证券报）", "important": 0, "vip": 0, "tags": [], "id": "sina5110649"}, {"src": "sina", "time": "2026-09-24 07:24:51", "ts": "2026-09-24 07:24:51", "content": "委内瑞拉代总统罗德里格斯：委内瑞拉已开启民主进程。", "important": 0, "vip": 0, "tags": [], "id": "sina5110648"}, {"src": "sina", "time": "2026-09-24 07:23:51", "ts": "2026-09-24 07:23:51", "content": "【孟加拉航空订购11架波音飞机】一份联合声明显示，孟加拉航空已向波音订购11架787梦想客机与737MAX飞机。本次采购包含5架787-10以及6架737-8飞机，是在今年早些时候孟加拉航空史上最大一笔订单（14架787梦想客机和737MAX飞机）基础上追加的采购。", "important": 0, "vip": 0, "tags": [], "id": "sina5110647"}, {"src": "sina", "time": "2026-09-24 07:22:51", "ts": "2026-09-24 07:22:51", "content": "委内瑞拉：和美国正努力通过对话解决分歧。", "important": 0, "vip": 0, "tags": [], "id": "sina5110646"}, {"src": "sina", "time": "2026-09-24 07:22:42", "ts": "2026-09-24 07:22:42", "content": "美国将出资70亿美元用于阿根廷的关键矿产和能源项目。", "important": 0, "vip": 0, "tags": [], "id": "sina5110645"}, {"src": "sina", "time": "2026-09-24 07:21:25", "ts": "2026-09-24 07:21:25", "content": "META宣布为其人工智能助手MUSE建立新的合作伙伴关系。", "important": 0, "vip": 0, "tags": [], "id": "sina5110644"}, {"src": "sina", "time": "2026-09-24 07:20:39", "ts": "2026-09-24 07:20:39", "content": "委内瑞拉代总统罗德里格斯：感谢美国总统唐纳德·特朗普恢复两国外交关系。", "important": 0, "vip": 0, "tags": [], "id": "sina5110643"}], "lme": [{"date": "2026-09-22", "sn_cash": 53745.0, "sn_m3": 54000.0, "sn_stock": 4645.0, "cu_cash": 14797.0, "cu_m3": 14760.0, "cu_stock": 254250.0}, {"date": "2026-09-21", "sn_cash": 53785.0, "sn_m3": 54045.0, "sn_stock": 4780.0, "cu_cash": 14788.0, "cu_m3": 14730.0, "cu_stock": 255875.0}, {"date": "2026-09-18", "sn_cash": 53600.0, "sn_m3": 53700.0, "sn_stock": 4855.0, "cu_cash": 14529.0, "cu_m3": 14515.0, "cu_stock": 255100.0}, {"date": "2026-09-17", "sn_cash": 53000.0, "sn_m3": 53090.0, "sn_stock": 4965.0, "cu_cash": 14400.5, "cu_m3": 14409.0, "cu_stock": 255900.0}, {"date": "2026-09-16", "sn_cash": 52310.0, "sn_m3": 52700.0, "sn_stock": 4990.0, "cu_cash": 14227.0, "cu_m3": 14232.0, "cu_stock": 254150.0}, {"date": "2026-09-15", "sn_cash": 51800.0, "sn_m3": 52000.0, "sn_stock": 4890.0, "cu_cash": 14045.0, "cu_m3": 14077.0, "cu_stock": 249225.0}, {"date": "2026-09-14", "sn_cash": 52200.0, "sn_m3": 52400.0, "sn_stock": 5120.0, "cu_cash": 14044.0, "cu_m3": 14065.5, "cu_stock": 242900.0}, {"date": "2026-09-11", "sn_cash": 53755.0, "sn_m3": 54000.0, "sn_stock": 5200.0, "cu_cash": 14238.5, "cu_m3": 14233.0, "cu_stock": 234475.0}, {"date": "2026-09-10", "sn_cash": 54750.0, "sn_m3": 54910.0, "sn_stock": 5155.0, "cu_cash": 14390.0, "cu_m3": 14371.0, "cu_stock": 234750.0}, {"date": "2026-09-09", "sn_cash": 55000.0, "sn_m3": 55150.0, "sn_stock": 5260.0, "cu_cash": 14672.0, "cu_m3": 14632.0, "cu_stock": 235825.0}], "shfe": {"updated": "2026-09-23 20:57", "metals": {"sn": {"name": "期货库存:锡:总计", "display_id": "S005580468", "unit": "吨", "source": "上海期货交易所·iFinD EDB", "series": [["2026-07-17", 4521.0], ["2026-07-24", 4322.0], ["2026-07-31", 4341.0], ["2026-08-07", 4848.0], ["2026-08-14", 5452.0], ["2026-08-21", 5340.0], ["2026-08-28", 5479.0], ["2026-09-04", 4657.0], ["2026-09-11", 6277.0], ["2026-09-18", 4979.0]], "latest": ["2026-09-18", 4979.0]}, "cu": {"name": "期货库存:铜", "display_id": "S000025739", "unit": "吨", "source": "上海期货交易所·iFinD EDB", "series": [["2026-07-17", 39652.0], ["2026-07-24", 28668.0], ["2026-07-31", 25563.0], ["2026-08-07", 22977.0], ["2026-08-14", 33676.0], ["2026-08-21", 46105.0], ["2026-08-28", 31462.0], ["2026-09-04", 25781.0], ["2026-09-11", 20854.0], ["2026-09-18", 26655.0]], "latest": ["2026-09-18", 26655.0]}}}};